import java.io.RandomAccessFile;
import java.nio.MappedByteBuffer;
import java.nio.channels.FileChannel;

public class Main {
    public static void main(String[] args) throws Exception {
        try (RandomAccessFile raf = new RandomAccessFile("nums.dat", "rw")) {
            for (int i = 1; i <= 5; i++) raf.writeInt(i * 10);
            raf.seek(0);
            System.out.println("sequential read  : " + raf.readInt() + " " + raf.readInt());
            raf.seek(3L * 4);
            System.out.println("seek to index 3  : " + raf.readInt());
            System.out.println("file length      : " + raf.length() + " bytes (5 ints x 4)");
            raf.seek(4L * 4);
            raf.writeInt(999);
        }

        try (RandomAccessFile raf = new RandomAccessFile("nums.dat", "rw");
             FileChannel ch = raf.getChannel()) {
            MappedByteBuffer map = ch.map(FileChannel.MapMode.READ_WRITE, 0, ch.size());
            System.out.println("mapped size      : " + map.capacity());
            System.out.println("index 4 via map  : " + map.getInt(4 * 4));
            map.putInt(0, 111);
            map.force();
            System.out.println("wrote 111 at idx0: " + map.getInt(0));
        }

        try (RandomAccessFile raf = new RandomAccessFile("nums.dat", "r")) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 5; i++) sb.append(raf.readInt()).append(i == 4 ? "" : " ");
            System.out.println("final content    : " + sb);
        }
    }
}
